import{_ as s,O as a,o as r,c as i,a as o,i as n,f as d}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"D.14　社会理论、权力、交往与制度再生产","description":"","frontmatter":{"title":"D.14　社会理论、权力、交往与制度再生产","xkChars":684,"xkLessons":{"D.14":{"title":"D.14　社会理论、权力、交往与制度再生产","lead":"一项申诉得到认真复核后维持原决定，和根本没审就维持决定，表面结果相同，质量却不同。研究制度与权力，需要追踪理由、材料和权限怎样作用，不能只数改了多少次。","explanation":["原文定位：第4737—4752行；原文锚点 section-d-14；短引文：‘变化率不能替代质量判断。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","形成、维持、功能、社会承认、法律有效和规范正当是不同问题。制度怎样出现，不等于今天靠什么维持；某制度产生某功能，也不证明这个功能就是它的起源，更不证明它合法或正当。应先列清问题，避免用一个结构强度或制度成功标签包办全部。","功能主义、理解社会学、互动论、结构化与形态生成、权力知识研究、公共交往、社会系统理论和行动者网络保留各自对象。结果关系、行动意义、现场秩序、时间过程、分类与权力、沟通以及物技术的参与，不能都改写成同一项结构量。具体借用须看原论证的单位与强承诺，而不是只收集相似词汇。","公开服从的动机可能是认可、习惯、收入依赖、威胁或没有替代。同一动作不足以识别其中哪一种；行动者理由、现实选项与约束需要分别核。理解一项沟通不代表同意，能够准确复述规定也不证明自愿接受，不能从可观察顺从倒填规范认同。","法律文本形成理由，与服务实际抵达是不同环节。决定书可能正确援引规则，仍需确认资源、人员和实施条件是否让人真正得到服务。物与技术也可有因果作用，例如表单或设备改变可见性和操作机会，但这不等于机器或物件因此承担人的道德责任。因果行动位置与责任主体须分开。","规则不只有压制功能，也可能让协调、可预期性和权利要求成为可能。应核规则在具体通道里如何运行：谁被分类、如何训练、记录什么、奖惩怎样发生、谁有决定和复核权。批评不能只说存在权力，也不能由规则有协调效用就取消对分类与排除的追踪。","参与可能纠错，也可能只增加表达而不改变权限。会议人数、意见条数和满意表情不能证明意见能影响关键判断。一般程序若认真理解材料并合理拒绝某项请求，仍可具有尊重与知识价值；参与有效不要求每个要求都获采纳。但只听见声音而无实际处理，也不能拿程序形式替代回应。","这里需要分三层记录：实际因果反馈、一般参与质量、Xikari自身GOV-02版本采用许可。某申诉改变资源安排，可支持相应变化，分配正当另判；某要求有理由不采纳，可支持一般回应质量，不能写请求已采纳；框架内部applied还受16.2的专门条件约束，不能由任何一层自动认证另一层。[来源：theory-gov02]","GOV-02要求每条异议有处置、理由、所用证据及对文本流程行动上限的影响，采纳效果绑定实际change_id，有理由未采纳仍保留。applied不要求象征性接纳至少一项，而要求可能改变关键判断、保护或权限的理由都获相称处理。此类关键异议未决、必要独立复核缺失或不得豁免事项未满足时，暂停受影响采用；也不能把反对仍在一概当永久否决。决定标准应事前公布、可申诉且能独立审查。[来源：theory-gov02]","制度可通过熟练实践、预算、工具、非正式承诺与人员安排反复实现，不必每次改章程。文书没变而实际分工重组，或者文书修改但执行如旧，都值得研究。制度再生产不只是复制一段文字，也不必被理解为从未发生任何变化；应看实际工作如何持续实现及在何处发生位移。","复核后维持正确决定，与未真正审查而维持决定，可以通过理由是否针对材料、是否处理反例、是否有相应权限等区分。改判率低不自动证明没有复核，高也不自动证明更公平；原始错误率、案件进入和标准都可能不同。变化率是有限描述，不能代替质量判断，更不能为了达成改动指标象征性接纳无关建议。","九个入口依次是Durkheim、Parsons、Merton的社会事实功能，Weber理解社会学，Mead、Blumer、Goffman的互动秩序，Giddens与Archer的结构化与形态生成，Foucault权力知识，法兰克福学派与Habermas公共交往，Luhmann系统理论，冲突整合再生产，以及Latour行动者网络。最强反方担心有理由拒绝会成为任意拒绝的借口；回应是理由必须接受材料、反例和独立审查，而非由决定者自称充分。"],"distinctions":[{"leftTitle":"理解沟通","leftText":"能解释对方所说的内容。","rightTitle":"同意与认同","rightText":"须另有相应意愿材料，服从也可能来自约束。"},{"leftTitle":"形式文本变化","leftText":"文件内容更新。","rightTitle":"实践重组","rightText":"实际预算人员工具流程改变可与文书不同步。"},{"leftTitle":"一般回应","leftText":"问题得到材料支持的有理由处置。","rightTitle":"请求被采纳","rightText":"需确认提出的要求实际被接受或实施。"},{"leftTitle":"实际反馈改变","leftText":"判断流程或资源发生变化。","rightTitle":"规范正当","rightText":"变化本身不证明分配或权限正确。"},{"leftTitle":"GOV-02 applied","leftText":"满足框架内部专门采用合同。","rightTitle":"象征性接受或永久否决","rightText":"两种极端都不能代替关键异议处理及必要独立复核。"}],"boundaries":["不将服从直接判作认同，不把物技术的因果作用写成人的道德责任。","不把所有社会理论折成结构强度，也不假装已读目录下全部研究。","一般程序合理拒绝与GOV-02采用是不同层次；关键异议未决按受影响范围暂停。","有理由维持正确决定可具回应价值，但理由真实性和复核质量必须可检验。","全部申诉与机构例为教学构造，不裁定真实法律争议或修改任何实际权限。"],"questions":["一般有理由拒绝与请求被采纳如何分开？","为什么applied不要求象征性接受至少一项？","文书不变为何仍可能有制度变化？","评价申诉质量为什么不能只看改判率？"],"diagramPath":"/reading-assets/S-D-14/figures/section-d-14.png","caseLinks":[{"title":"真实原则文本：RFC7282中的异议处理","href":"https://www.rfc-editor.org/rfc/rfc7282.html"}],"caseNotes":[{"title":"真实原则文本：RFC7282中的异议处理","text":"RFC7282是2014年6月发布的Informational文件，明确不是变更IETF程序的BCP。其第3节说明，应实质处理异议并对未被满足的关切给出理由；持续有人不满意不必然阻止粗略共识，忽略问题却不能靠多数支持补正。这里借用其公开原则区分处理与采纳，不把文中假想协议争论当成真实会议事件。","sourceLabel":"RFC7282，On Consensus and Humming in the IETF，June2014，Informational","sourceUrl":"https://www.rfc-editor.org/rfc/rfc7282.html","sourceLocator":"首页Abstract注与Status；§3印刷pp7—9，尤其p9 Any finding…与Remember…两段及p10续句","boundary":"文件描述原则，不证明现实每次讨论都依此运作，不替代Xikari GOV-02专门合同或其他组织法定权限。","href":"https://www.rfc-editor.org/rfc/rfc7282.html"}],"sourceRefs":[{"section":"D.14","start_line":4737,"end_line":4752,"startLine":4737,"endLine":4752}],"outputId":"section-d-14","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["分开形成维持功能承认法律有效与规范正当，定位所借理论单位。","核行动意义、现实约束与服务实施，不由服从推认同、不由文本推到达。","沿分类训练记录奖惩与决定复核权追踪实际通道。","分别记录因果反馈、一般参与与GOV-02采用资格，关键异议按预先可审查标准处置。","检查文书与实际过程是否一致，评价复核理由与材料而非只看变化率。"],"teachingExamples":[{"title":"原文教学例展开：有理由维持","text":"假想申请人提出申诉，审查者核对全部关键材料、回应反例并说明原决定为何仍成立。可以登记一般回应与复核确实发生，不能说申请人要求已获采纳。若还要申请框架内部采用许可，仍须逐项核GOV-02条件，不能用这一件申诉代替全部合同。","assumptions":"沿原文构造，材料充分是明确设定。","boundary":"现实理由是否充分需独立核，不接受审查者单方面自证。"},{"title":"原文教学例展开：改了也未必正当","text":"假想另一申诉使组织修改规则并增加某群体资源，可确认意见进入实践的反馈。但该调整是否侵害其他群体、是否满足权利底线和授权要求，仍须另外判断。实际改变不是分配正当的充分条件。","assumptions":"机构资源与群体均虚构。","boundary":"未实施真实分配，不以教学改变证明净改善。"},{"title":"教学构造：同样零改判，两种复核","text":"设两个假想流程各处理10件案件，均维持全部决定。甲流程原决定均正确且逐件完成适当独立复核；乙流程从不读材料直接盖章。二者改判率都是0/10=0，但过程与知识质量不同。变化率不能独自识别是否有效复核。","assumptions":"案件正确性及流程细节为教学设定，非真实司法统计。","boundary":"不声称零改判总是好或坏，也不认为只需有文字理由即可。"},{"title":"教学构造：章程未改、实施改变","text":"假想章程维持不变，但预算从集中窗口转向流动服务，人员排班和工具同步改变。实际服务过程可以重组；反之仅修章程而无资源人员改变，不自动证明服务已经抵达。","assumptions":"非实际行政项目。","boundary":"每项变化与效果都需材料，不能由某个文件时间戳推断。"}],"counterexamples":[{"identity":"constructed_boundary","text":"反对意见还存在，所以任何决定永远不能采用。","effect":"关键在异议是否按适当标准获相称处理及必要复核，不是要求所有人内心满意。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"为了得到applied，象征性接受一个无关意见即可。","effect":"GOV-02看可能影响关键判断保护权限的理由是否处理，不靠象征采纳。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"十件都维持原决定，所以审查肯定只是形式。","effect":"须核原决定质量和实际复核，零改判构造说明结果率不足。","sourceIds":["theory"]}],"questionAnswers":[{"question":"一般有理由拒绝与请求被采纳如何分开？","answer":"前者说明处理质量，后者说明具体要求获接受；一真不要求另一真。","basis":"本节原文及上述公开推导"},{"question":"为什么applied不要求象征性接受至少一项？","answer":"合同要求关键理由获相称处理，真正采纳须有实际改变，形式采纳不补缺失复核。","basis":"本节原文及上述公开推导"},{"question":"文书不变为何仍可能有制度变化？","answer":"预算、工具、人员、熟练实践和非正式承诺可重组实际过程。","basis":"本节原文及上述公开推导"},{"question":"评价申诉质量为什么不能只看改判率？","answer":"结果相同可能来自正确复核或完全不审，必须核材料、理由、权限及适当纠错能力。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-14/figures/section-d-14.png","alt":"形成／维持／功能，承认／法律有效，规范正当分开；服从≠认同，文本≠服务抵达，技术因果≠人的责任；分类训练记录奖惩，决定与复核权限，追踪实际通道；因果反馈，一般参与质量，GOV-02许可三层；关键异议相称处理，必要独立复核，采纳核实际改动；文书实践可不同步，维持正确决定可有效，变化率不代质量。作者依D.14及16.2绘制；申诉和零改判例均为教学构造，非实际权限裁决。","caption":"作者依D.14及16.2绘制；申诉和零改判例均为教学构造，非实际权限裁决。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换异议是否实质处理、是否有必要复核和实际改动，分别显示参与质量与采用资格。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"原始原则文件展示回应与满足要求的区别，并清楚区分其信息性身份与框架内部许可。"},"openQuestions":["未取得14.01—14.09全部理论原文，未解决各理论内部与相互争论。","未核现实IETF具体会议与申诉实施，案例只支持原始文件内容。"],"taskId":"S-D-14","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4737—4752行；每节精确范围见sourceRefs","claim_support":["D.14：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-gov02","title":"原书16.2 GOV-02共识程序与版本权限","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"原书第3290—3310行，尤其末段逐异议处置与applied条件","claim_support":["关键异议相称处理、独立复核、实际change_id与受影响采用暂停"],"limits":["框架内部合同，不直接替代其他组织法定程序。"],"access_status":"partially_read"},{"id":"rfc7282","title":"On Consensus and Humming in the IETF","url":"https://www.rfc-editor.org/rfc/rfc7282.html","source_type":"primary","version_or_date":"June2014","locator":"Abstract注及Status；§3印刷pp7—9，p9 Any finding…及Remember…，p10续句","claim_support":["Informational身份与非BCP；异议须实质处理及有理由未满足，不由人数替代"],"limits":["原则文件而非现实个案实施证明；不能替代GOV-02。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-14/lecture.md","sourcesPath":"/reading-assets/S-D-14/sources.json","sourceSlicePath":"/reading-assets/S-D-14/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-14/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-14.md","filePath":"theory/appendix-d/d-14.md"}'),c={name:"theory/appendix-d/d-14.md"};function l(p,e,u,m,f,h){const t=a("SectionLesson");return r(),i("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-14" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.14</span><span class="xk-num__gap">　</span></span>社会理论、权力、交往与制度再生产 <a class="header-anchor" href="#section-d-14" aria-label="Permalink to &quot;D.14　社会理论、权力、交往与制度再生产 {#section-d-14}&quot;">​</a></h1><p>正文连接：§3.3；§7.6；§10—11；§14.5；§16.2。研究入口：14.01—14.09。</p><p>形成、维持、功能、社会承认、法律有效和规范正当是不同问题。功能主义的结果关系、理解社会学的行动意义、互动论的现场秩序、结构化与形态生成的时间过程、权力知识研究、公共交往、社会系统理论及行动者网络，不能全被折成一项“结构强度”。</p><p>公开服从可以来自认可、习惯、收入依赖、威胁或缺少替代；同一个行为不足以识别动机。理解一项沟通不等同意，文本中形成法律理由不等服务已经抵达，物和技术有因果作用不等承担人的道德责任。规则既可能约束，也可能使协调与权利要求成为可能。</p><p>批评要追踪分类、训练、记录、奖惩与决定权的具体通道。参与可以纠错，也可能只是增加表达而未改变权限。一般程序合理拒绝某项要求，仍可能具有尊重与知识价值；GOV-02对框架内部采用要求逐条有理由处置、必要的独立复核与实际改动核验；不能用象征性采纳取得applied，也不能把反对意见仍然存在一概当作永久否决。</p><p>教学例：一个申诉被听取并收到有理由的答复，原决定因证据充分而保留。这可以说明一般回应确实发生；不能因此宣称申请人要求被采纳。另一申诉导致规则和资源实际改变，也不能只凭改变本身证明分配正当。因果反馈、一般参与和框架自身版本许可分三层记录。</p><p>制度可以通过熟练实践、预算、工具、非正式承诺和人员安排反复实现，不以章程每次改写为条件。文书不变而实际过程重组、文书改变而执行不变，都有可研究的机制。复核维持正确决定与未真正审查而维持决定，虽然表面结果相同，仍可在理由、材料处理和权限上区分；变化率不能替代质量判断。</p><p>专题定位：14.01 社会事实与功能主义：Durkheim、Parsons、Merton；14.02 理解社会学：Weber；14.03 符号互动与日常秩序：Mead、Blumer、Goffman；14.04 结构化、形态生成与能动性：Giddens、Archer；14.05 权力、知识、规训与治理术：Foucault；14.06 批判理论与公共交往：法兰克福学派、Habermas；14.07 社会系统理论：Luhmann；14.08 冲突、整合与制度再生产；14.09 行动者网络与非人行动位置：Latour。</p></div>',1)),n(t,{section:"D.14"}),e[1]||(e[1]=d("div",{class:"theory-source"},null,-1))])}const b=s(c,[["render",l]]);export{g as __pageData,b as default};
